12: #define DRIVER_NAME "rtsa_dma"
13: 
14: struct dma_slot {
15:     void *vaddr;             // CPU 虚拟地址（指向大块内存中的偏移）
16:     dma_addr_t paddr;        // DMA 物理总线地址（指向大块内存中的偏移）
17:     struct rtsa_buffer_info info;
18: };
19: 
20: struct rtsa_dma_dev {
21:     struct platform_device *pdev;
22:     struct cdev cdev;
23:     dev_t dev_node;
24:     struct class *class;
25:     struct device *device;
26: 
27:     struct dma_chan *rx_chan;
28:     struct dma_slot slots[RTSA_RING_BUFFER_COUNT];
29: 
30:     // ===== 修改1：新增大块连续内存的基址记录 =====
31:     void *dma_base_vaddr;       // 大块内存的 CPU 虚拟基址
32:     dma_addr_t dma_base_paddr;  // 大块内存的 DMA 物理基址
33:     size_t dma_total_size;      // 总大小
34: 
35:     // 环形缓冲队列索引与同步
36:     wait_queue_head_t rx_wait;
37:     spinlock_t lock;
38:     __u32 completed_head;
39:     __u32 completed_tail;
40:     __u32 completed_queue[RTSA_RING_BUFFER_COUNT];
41:     
42:     bool is_running;
43:     __u64 frame_seq;
44: };
