46: // DMA 完成中断回调函数（运行在中断底半部/Tasklet 上下文）
47: static void rtsa_dma_rx_callback(void *param) {
48:     struct rtsa_dma_dev *rtsa = (struct rtsa_dma_dev *)param;
49:     unsigned long flags;
50:     __u32 slot_idx;
51: 
52:     spin_lock_irqsave(&rtsa->lock, flags);
53:     if (!rtsa->is_running) {
54:         spin_unlock_irqrestore(&rtsa->lock, flags);
55:         return;
56:     }
57: 
58:     slot_idx = rtsa->completed_queue[rtsa->completed_head];
59:     rtsa->slots[slot_idx].info.sequence = ++rtsa->frame_seq;
60:     rtsa->slots[slot_idx].info.timestamp_ns = ktime_get_ns();
61:     rtsa->slots[slot_idx].info.size = RTSA_BUFFER_SIZE;
62:     rtsa->slots[slot_idx].info.status = 0;
63: 
64:     rtsa->completed_head = (rtsa->completed_head + 1) % RTSA_RING_BUFFER_COUNT;
65:     spin_unlock_irqrestore(&rtsa->lock, flags);
66: 
67:     wake_up_interruptible(&rtsa->rx_wait);
68: }
69: 
70: // 提交一个 DMA 接收描述符到 DMAEngine
71: static int rtsa_submit_rx_slot(struct rtsa_dma_dev *rtsa, __u32 slot_idx) {
72:     struct dma_async_tx_descriptor *desc;
73:     dma_cookie_t cookie;
74: 
75:     desc = dmaengine_prep_slave_single(
76:         rtsa->rx_chan,
77:         rtsa->slots[slot_idx].paddr,
78:         RTSA_BUFFER_SIZE,
79:         DMA_DEV_TO_MEM,
80:         DMA_PREP_INTERRUPT | DMA_CTRL_ACK
81:     );
82: 
83:     if (!desc) {
84:         dev_err(&rtsa->pdev->dev, "Failed to prepare DMA descriptor\n");
85:         return -ENOMEM;
86:     }
87: 
88:     desc->callback = rtsa_dma_rx_callback;
89:     desc->callback_param = rtsa;
90: 
91:     cookie = dmaengine_submit(desc);
92:     if (dma_submit_error(cookie)) {
93:         dev_err(&rtsa->pdev->dev, "DMA submit error\n");
94:         return -EIO;
95:     }
96: 
97:     dma_async_issue_pending(rtsa->rx_chan);
98:     return 0;
99: }
100: 
101: // ===== 修改2：安全的 mmap，基于大块连续内存基址 =====
102: static int rtsa_dma_mmap(struct file *filp, struct vm_area_struct *vma) {
103:     struct rtsa_dma_dev *rtsa = filp->private_data;
104:     size_t map_size = vma->vm_end - vma->vm_start;
105: 
106:     // 安全检查：必须从文件头开始映射（避免随机偏移）
107:     if (vma->vm_pgoff != 0) {
108:         pr_err("rtsa_dma: mmap offset must be 0\n");
109:         return -EINVAL;
110:     }
111: 
112:     if (map_size > rtsa->dma_total_size) {
113:         pr_err("rtsa_dma: mmap size %zu exceeds total %zu\n", 
114:                map_size, rtsa->dma_total_size);
115:         return -EINVAL;
116:     }
117: 
118:     // 直接映射大块物理连续内存
119:     return dma_mmap_coherent(&rtsa->pdev->dev, vma,
120:                              rtsa->dma_base_vaddr,
121:                              rtsa->dma_base_paddr,
122:                              map_size);
123: }
124: 
125: static __poll_t rtsa_dma_poll(struct file *filp, struct poll_table_struct *wait) {
126:     struct rtsa_dma_dev *rtsa = filp->private_data;
127:     __poll_t mask = 0;
128:     unsigned long flags;
129: 
130:     poll_wait(filp, &rtsa->rx_wait, wait);
131: 
132:     spin_lock_irqsave(&rtsa->lock, flags);
133:     if (rtsa->completed_head != rtsa->completed_tail) {
134:         mask |= EPOLLIN | EPOLLRDNORM;
135:     }
136:     spin_unlock_irqrestore(&rtsa->lock, flags);
137: 
138:     return mask;
139: }
140: 
141: static long rtsa_dma_ioctl(struct file *filp, unsigned int cmd, unsigned long arg) {
142:     struct rtsa_dma_dev *rtsa = filp->private_data;
143:     unsigned long flags;
144:     int ret = 0;
145: 
146:     switch (cmd) {
147:     case RTSA_IOC_START: {
148:         // ===== 修改3：在自旋锁外提交描述符，防止在锁内睡眠 =====
149:         spin_lock_irqsave(&rtsa->lock, flags);
150:         if (!rtsa->is_running) {
151:             rtsa->is_running = true;
152:             rtsa->completed_head = 0;
153:             rtsa->completed_tail = 0;
154:             // 预填完成队列的索引（在锁内完成，保证回调看到有效值）
155:             for (int i = 0; i < RTSA_RING_BUFFER_COUNT / 2; i++) {
156:                 rtsa->completed_queue[i] = i;
157:             }
158:         }
159:         spin_unlock_irqrestore(&rtsa->lock, flags);
160: 
161:         // 在锁外提交硬件描述符（因为 dmaengine_prep 可能睡眠）
162:         if (rtsa->is_running) {
163:             for (int i = 0; i < RTSA_RING_BUFFER_COUNT / 2; i++) {
164:                 ret = rtsa_submit_rx_slot(rtsa, i);
165:                 if (ret) {
166:                     dev_err(&rtsa->pdev->dev, "Failed to submit initial slot %d\n", i);
167:                     // 如果提交失败，停止硬件标记，防止脏状态
168:                     spin_lock_irqsave(&rtsa->lock, flags);
169:                     rtsa->is_running = false;
170:                     spin_unlock_irqrestore(&rtsa->lock, flags);
171:                     return ret;
172:                 }
173:             }
174:         }
175:         break;
176:     }
177: 
178:     case RTSA_IOC_STOP:
179:         spin_lock_irqsave(&rtsa->lock, flags);
180:         rtsa->is_running = false;
181:         spin_unlock_irqrestore(&rtsa->lock, flags);
182:         dmaengine_terminate_sync(rtsa->rx_chan);
183:         wake_up_interruptible(&rtsa->rx_wait);
184:         break;
185: 
186:     case RTSA_IOC_DEQUEUE: {
187:         struct rtsa_buffer_info info;
188:         spin_lock_irqsave(&rtsa->lock, flags);
189:         if (rtsa->completed_head == rtsa->completed_tail) {
190:             spin_unlock_irqrestore(&rtsa->lock, flags);
191:             return -EAGAIN;
192:         }
193:         __u32 slot = rtsa->completed_queue[rtsa->completed_tail];
194:         info = rtsa->slots[slot].info;
195:         info.index = slot;
196:         rtsa->completed_tail = (rtsa->completed_tail + 1) % RTSA_RING_BUFFER_COUNT;
197:         spin_unlock_irqrestore(&rtsa->lock, flags);
198: 
199:         if (copy_to_user((void __user *)arg, &info, sizeof(info)))
200:             return -EFAULT;
201:         break;
202:     }
203: 
204:     case RTSA_IOC_QUEUE: {
205:         __u32 slot_idx;
206:         if (copy_from_user(&slot_idx, (void __user *)arg, sizeof(slot_idx)))
207:             return -EFAULT;
208:         if (slot_idx >= RTSA_RING_BUFFER_COUNT)
209:             return -EINVAL;
210: 
211:         ret = rtsa_submit_rx_slot(rtsa, slot_idx);
212:         break;
213:     }
214: 
215:     default:
216:         ret = -ENOTTY;
217:     }
218: 
219:     return ret;
220: }
221: 
222: static int rtsa_dma_open(struct inode *inode, struct file *filp) {
223:     struct rtsa_dma_dev *rtsa = container_of(inode->i_cdev, struct rtsa_dma_dev, cdev);
224:     filp->private_data = rtsa;
225:     return 0;
226: }
227: 
228: static const struct file_operations rtsa_dma_fops = {
229:     .owner          = THIS_MODULE,
230:     .open           = rtsa_dma_open,
231:     .mmap           = rtsa_dma_mmap,
232:     .poll           = rtsa_dma_poll,
233:     .unlocked_ioctl = rtsa_dma_ioctl,
234: };
