236: // ===== 修改4：安全的 probe（一次申请 + 错误回滚） =====
237: static int rtsa_dma_probe(struct platform_device *pdev) {
238:     struct rtsa_dma_dev *rtsa;
239:     int ret, i;
240: 
241:     rtsa = devm_kzalloc(&pdev->dev, sizeof(*rtsa), GFP_KERNEL);
242:     if (!rtsa)
243:         return -ENOMEM;
244: 
245:     rtsa->pdev = pdev;
246:     spin_lock_init(&rtsa->lock);
247:     init_waitqueue_head(&rtsa->rx_wait);
248: 
249:     // 1. 获取 DMA 通道
250:     rtsa->rx_chan = dma_request_chan(&pdev->dev, "rx_chan");
251:     if (IS_ERR(rtsa->rx_chan)) {
252:         dev_err(&pdev->dev, "Failed to request DMA channel\n");
253:         return PTR_ERR(rtsa->rx_chan);
254:     }
255: 
256:     // ===== 核心修改：一次性申请所有缓冲区（物理连续） =====
257:     rtsa->dma_total_size = RTSA_RING_BUFFER_COUNT * RTSA_BUFFER_SIZE;
258:     rtsa->dma_base_vaddr = dma_alloc_coherent(
259:         &pdev->dev,
260:         rtsa->dma_total_size,
261:         &rtsa->dma_base_paddr,
262:         GFP_KERNEL
263:     );
264:     if (!rtsa->dma_base_vaddr) {
265:         dev_err(&pdev->dev, "Failed to allocate contiguous DMA memory\n");
266:         ret = -ENOMEM;
267:         goto err_free_chan;
268:     }
269: 
270:     // 2. 将大块内存切分成虚拟环，每个 slot 指向对应偏移
271:     for (i = 0; i < RTSA_RING_BUFFER_COUNT; i++) {
272:         rtsa->slots[i].vaddr = rtsa->dma_base_vaddr + i * RTSA_BUFFER_SIZE;
273:         rtsa->slots[i].paddr = rtsa->dma_base_paddr + i * RTSA_BUFFER_SIZE;
274:         memset(&rtsa->slots[i].info, 0, sizeof(rtsa->slots[i].info));
275:     }
276: 
277:     // 3. 注册字符设备
278:     ret = alloc_chrdev_region(&rtsa->dev_node, 0, 1, DRIVER_NAME);
279:     if (ret) {
280:         dev_err(&pdev->dev, "Failed to alloc chrdev region\n");
281:         goto err_free_dma;
282:     }
283:     cdev_init(&rtsa->cdev, &rtsa_dma_fops);
284:     ret = cdev_add(&rtsa->cdev, rtsa->dev_node, 1);
285:     if (ret) {
286:         dev_err(&pdev->dev, "Failed to add cdev\n");
287:         goto err_unregister_region;
288:     }
289: 
290:     rtsa->class = class_create(THIS_MODULE, DRIVER_NAME);
291:     if (IS_ERR(rtsa->class)) {
292:         ret = PTR_ERR(rtsa->class);
293:         goto err_cdev_del;
294:     }
295: 
296:     rtsa->device = device_create(rtsa->class, NULL, rtsa->dev_node, NULL, DRIVER_NAME);
297:     if (IS_ERR(rtsa->device)) {
298:         ret = PTR_ERR(rtsa->device);
299:         goto err_class_destroy;
300:     }
301: 
302:     platform_set_drvdata(pdev, rtsa);
303:     dev_info(&pdev->dev, "RTSA DMA probed, total size: %zu bytes\n", rtsa->dma_total_size);
304:     return 0;
305: 
306: // 错误回滚标签
307: err_class_destroy:
308:     class_destroy(rtsa->class);
309: err_cdev_del:
310:     cdev_del(&rtsa->cdev);
311: err_unregister_region:
312:     unregister_chrdev_region(rtsa->dev_node, 1);
313: err_free_dma:
314:     dma_free_coherent(&pdev->dev, rtsa->dma_total_size,
315:                       rtsa->dma_base_vaddr, rtsa->dma_base_paddr);
316: err_free_chan:
317:     dma_release_channel(rtsa->rx_chan);
318:     return ret;
319: }
320: 
321: // ===== 修改5：安全的 remove（一次性释放 + 停止硬件） =====
322: static int rtsa_dma_remove(struct platform_device *pdev) {
323:     struct rtsa_dma_dev *rtsa = platform_get_drvdata(pdev);
324: 
325:     // 1. 先停止硬件，防止还在传输
326:     if (rtsa->is_running) {
327:         dmaengine_terminate_sync(rtsa->rx_chan);
328:     }
329: 
330:     // 2. 销毁设备节点
331:     device_destroy(rtsa->class, rtsa->dev_node);
332:     class_destroy(rtsa->class);
333:     cdev_del(&rtsa->cdev);
334:     unregister_chrdev_region(rtsa->dev_node, 1);
335: 
336:     // 3. 一次性释放大块连续内存
337:     if (rtsa->dma_base_vaddr) {
338:         dma_free_coherent(&pdev->dev, rtsa->dma_total_size,
339:                           rtsa->dma_base_vaddr, rtsa->dma_base_paddr);
340:     }
341: 
342:     // 4. 释放 DMA 通道
343:     if (rtsa->rx_chan) {
344:         dma_release_channel(rtsa->rx_chan);
345:     }
346: 
347:     return 0;
348: }
349: 
350: static const struct of_device_id rtsa_dma_of_match[] = {
351:     { .compatible = "rtsa,spectrum-dma" },
352:     { /* sentinel */ }
353: };
354: MODULE_DEVICE_TABLE(of, rtsa_dma_of_match);
355: 
356: static struct platform_driver rtsa_dma_driver = {
357:     .probe  = rtsa_dma_probe,
358:     .remove = rtsa_dma_remove,
359:     .driver = {
360:         .name = DRIVER_NAME,
361:         .of_match_table = rtsa_dma_of_match,
362:     },
363: };
364: module_platform_driver(rtsa_dma_driver);
