#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <poll.h>
#include <errno.h>
#include "rtsa_dma_uapi.h"

static volatile bool g_running = true;

static void sig_handler(int signo) {
    (void)signo;
    g_running = false;
}

static uint64_t get_time_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
}

static void print_hex_dump(const void *data, size_t len) {
    const uint8_t *p = (const uint8_t *)data;
    size_t display_len = len > 32 ? 32 : len;
    printf("    [Data Dump (first %zu bytes)]: ", display_len);
    for (size_t i = 0; i < display_len; i++) {
        printf("%02X ", p[i]);
    }
    if (len > 32) printf("...");
    printf("\n");
}

int main(int argc, char *argv[]) {
    const char *dev_path = "/dev/rtsa_dma";
    int timeout_ms = 3000;
    int fd;
    void *map_base;
    size_t total_map_size;
    int ret;

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) timeout_ms = 3000;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    printf("====================================================\n");
    printf("       RTSA AXI DMA 连通性与吞吐性能测试工具        \n");
    printf("====================================================\n");
    printf("[*] 正在打开设备: %s ...\n", dev_path);

    fd = open(dev_path, O_RDWR);
    if (fd < 0) {
        perror("[-] 打开设备失败");
        fprintf(stderr, "    请确认: 1. 是否执行了 insmod rtsa_dma.ko\n");
        fprintf(stderr, "            2. 是否有 root 权限\n");
        return -1;
    }

    total_map_size = (size_t)RTSA_RING_BUFFER_COUNT * RTSA_BUFFER_SIZE;
    printf("[*] 正在 mmap 环形内存 (16 槽位 x 256 KB = %zu MB) ...\n", 
           total_map_size / (1024 * 1024));

    map_base = mmap(NULL, total_map_size, PROT_READ, MAP_SHARED, fd, 0);
    if (map_base == MAP_FAILED) {
        perror("[-] mmap 内存映射失败");
        close(fd);
        return -1;
    }

    printf("[*] 正在启动 DMA 硬件通道 (RTSA_IOC_START) ...\n");
    if (ioctl(fd, RTSA_IOC_START) < 0) {
        perror("[-] 启动 DMA 失败");
        munmap(map_base, total_map_size);
        close(fd);
        return -1;
    }

    printf("[+] DMA 启动成功！正在等待 PL 端 AXI4-Stream 数据 (超时: %d ms) ...\n", timeout_ms);
    printf("--------------------------------------------------------------------\n");
    printf("%-10s %-12s %-12s %-12s %-10s %-10s\n", 
           "时间", "实时帧率", "实时带宽", "单帧大小", "累计帧数", "丢帧/溢出");
    printf("--------------------------------------------------------------------\n");

    uint64_t total_frames = 0;
    uint64_t total_bytes = 0;
    uint64_t last_seq = 0;
    uint64_t dropped_frames = 0;

    uint64_t interval_frames = 0;
    uint64_t interval_bytes = 0;
    uint64_t start_time = get_time_ns();
    uint64_t last_report_time = start_time;
    bool first_frame = true;

    while (g_running) {
        struct pollfd pfd = { .fd = fd, .events = POLLIN };
        ret = poll(&pfd, 1, timeout_ms);

        if (ret < 0) {
            if (errno == EINTR) break;
            perror("[-] poll 异常");
            break;
        }

        if (ret == 0) {
            printf("\n[!] 警告: 等待超时 (%d ms)！未收到 PL 端数据。\n", timeout_ms);
            printf("    排查建议:\n");
            printf("    1. PL 逻辑是否启动？(FFT/ADC 数据源是否处于 Run 状态)\n");
            printf("    2. PL 端 AXI-Stream 是否正确拉高了 TLAST 信号？\n");
            printf("    3. AXI DMA 的流时钟 (s_axis_s2mm_aclk) 是否正常震荡？\n");
            continue;
        }

        // 收到数据，取出缓冲描述信息
        struct rtsa_buffer_info info;
        if (ioctl(fd, RTSA_IOC_DEQUEUE, &info) < 0) {
            if (errno == EAGAIN) continue;
            perror("[-] DEQUEUE 失败");
            break;
        }

        // 校验序号与丢帧统计
        if (first_frame) {
            last_seq = info.sequence;
            first_frame = false;
            printf("[+] 成功收到第 1 帧数据！(Slot: %u, Size: %u bytes)\n", 
                   info.index, info.size);
            void *slot_ptr = (char *)map_base + (size_t)info.index * RTSA_BUFFER_SIZE;
            print_hex_dump(slot_ptr, info.size);
            printf("--------------------------------------------------------------------\n");
        } else {
            if (info.sequence > last_seq + 1) {
                dropped_frames += (info.sequence - last_seq - 1);
            }
            last_seq = info.sequence;
        }

        if (info.status != 0) {
            dropped_frames++;
        }

        total_frames++;
        total_bytes += info.size;
        interval_frames++;
        interval_bytes += info.size;

        // 归还槽位给驱动
        if (ioctl(fd, RTSA_IOC_QUEUE, &info.index) < 0) {
            perror("[-] QUEUE 归还槽位失败");
            break;
        }

        // 每秒统计一次性能
        uint64_t now = get_time_ns();
        uint64_t diff_ns = now - last_report_time;
        if (diff_ns >= 1000000000ULL) {
            double elapsed_sec = (double)diff_ns / 1.0e9;
            double fps = (double)interval_frames / elapsed_sec;
            double mbps = ((double)interval_bytes / (1024.0 * 1024.0)) / elapsed_sec;

            time_t rawtime;
            struct tm *timeinfo;
            char time_str[16];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(time_str, sizeof(time_str), "%H:%M:%S", timeinfo);

            printf("%-10s %-10.1f fps %-9.2f MB/s %-8.1f KB %-10llu %-10llu\n",
                   time_str,
                   fps,
                   mbps,
                   (double)info.size / 1024.0,
                   (unsigned long long)total_frames,
                   (unsigned long long)dropped_frames);
            fflush(stdout);

            interval_frames = 0;
            interval_bytes = 0;
            last_report_time = now;
        }
    }

    // 停止并清理
    printf("\n[*] 正在停止 DMA 传输并释放资源 ...\n");
    ioctl(fd, RTSA_IOC_STOP);
    munmap(map_base, total_map_size);
    close(fd);

    uint64_t total_time_ns = get_time_ns() - start_time;
    double total_sec = (double)total_time_ns / 1.0e9;
    printf("\n====================================================\n");
    printf("                  测试总结报告                      \n");
    printf("====================================================\n");
    printf("  运行总时长   : %.2f 秒\n", total_sec);
    printf("  接收总帧数   : %llu 帧\n", (unsigned long long)total_frames);
    printf("  传输总数据量 : %.2f MB\n", (double)total_bytes / (1024.0 * 1024.0));
    if (total_sec > 0.0) {
        printf("  平均帧率     : %.2f fps\n", (double)total_frames / total_sec);
        printf("  平均吞吐速率 : %.2f MB/s (%.2f Gbps)\n", 
               ((double)total_bytes / (1024.0 * 1024.0)) / total_sec,
               (((double)total_bytes * 8.0) / 1.0e9) / total_sec);
    }
    printf("  丢帧/溢出数  : %llu 帧\n", (unsigned long long)dropped_frames);
    printf("====================================================\n");

    return 0;
}

