398: int RasterSpectrumRenderer::yForAmplitude(const float amplitude) const noexcept
399: {
400:     const float safeAmp = std::isfinite(amplitude) ? amplitude : bottomLevel_;
401:     const float range = std::max(1.0F, referenceLevel_ - bottomLevel_);
402:     const float normalized = std::clamp((referenceLevel_ - safeAmp) / range, 0.0F, 1.0F);
403:     return plotRect_.top()
404:         + static_cast<int>(std::lround(normalized * static_cast<float>(plotRect_.height())));
