9: void EnvelopeReducer::reduce(const float* bins,
10:                              const std::size_t binCount,
11:                              const std::size_t pixelWidth,
12:                              std::vector<EnvelopeColumn>& output)
13: {
14:     output.clear();
15:     if (bins == nullptr || binCount == 0 || pixelWidth == 0) {
16:         return;
17:     }
18: 
19:     const std::size_t columnCount = std::min(binCount, pixelWidth);
20:     output.resize(columnCount);
21: 
22:     for (std::size_t column = 0; column < columnCount; ++column) {
23:         const std::size_t begin = (column * binCount) / columnCount;
24:         std::size_t end = ((column + 1U) * binCount) / columnCount;
25:         end = std::max(end, begin + 1U);
26:         end = std::min(end, binCount);
27: 
28:         float minimum = std::numeric_limits<float>::infinity();
29:         float maximum = -std::numeric_limits<float>::infinity();
30:         bool valid = false;
31: 
32:         for (std::size_t index = begin; index < end; ++index) {
33:             const float value = bins[index];
34:             if (!std::isfinite(value)) {
35:                 continue;
36:             }
37:             minimum = std::min(minimum, value);
38:             maximum = std::max(maximum, value);
39:             valid = true;
40:         }
41: 
42:         output[column] = EnvelopeColumn {
43:             valid ? minimum : 0.0F,
44:             valid ? maximum : 0.0F,
45:             begin,
46:             end - 1U,
47:             valid
48:         };
49:     }
