113: static int rtsa_submit_rx_slot(struct rtsa_dma_dev *rtsa, __u32 slot_idx) {
114:     struct dma_async_tx_descriptor *desc;
115:     struct dma_slot *slot;
116: 
117:     if (slot_idx >= RTSA_RING_BUFFER_COUNT)
118:         return -EINVAL;
119: 
120:     slot = &rtsa->slots[slot_idx];
121: 
122:     desc = dmaengine_prep_slave_single(
123:         rtsa->rx_chan,
124:         slot->paddr,
125:         RTSA_BUFFER_SIZE,
126:         DMA_DEV_TO_MEM,
127:         DMA_PREP_INTERRUPT | DMA_CTRL_ACK
128:     );
129: 
130:     if (!desc) {
131:         dev_err(&rtsa->pdev->dev, "Slot %u failed to prepare DMA descriptor\n", slot_idx);
132:         return -ENOMEM;
133:     }
134: 
135:     desc->callback = rtsa_dma_rx_callback;
136:     desc->callback_param = slot; // 关键修复：绑定当前 slot 结构体指针
137: 
138:     slot->state = SLOT_STATE_QUEUED;
139:     slot->cookie = dmaengine_submit(desc);
140:     if (dma_submit_error(slot->cookie)) {
141:         slot->state = SLOT_STATE_FREE;
142:         dev_err(&rtsa->pdev->dev, "Slot %u DMA submit error\n", slot_idx);
143:         return -EIO;
144:     }
145: 
146:     dma_async_issue_pending(rtsa->rx_chan);
147:     return 0;
148: }
