632: std::vector<std::size_t> SpectrumPlotWidget::findPeaks() const
633: {
634:     std::vector<std::size_t> peaks;
635:     if (!frame_ || frame_->bins.size() < 3) {
636:         return peaks;
637:     }
638: 
639:     const auto& data = frame_->bins;
640:     const std::size_t n = data.size();
641:     constexpr float kExcursion = 3.0F; // 工业标准 3 dB 峰值凸起高度 (Peak Excursion)
642: 
643:     for (std::size_t i = 0; i < n; ++i) {
644:         const float val = data[i];
645:         if (!std::isfinite(val) || val < peakThreshold_) {
646:             continue;
647:         }
648: 
649:         // 1. 局部极大值条件（不低于相邻有效采样点）
650:         const bool notBelowLeft = (i == 0 || !std::isfinite(data[i - 1]) || val >= data[i - 1]);
651:         const bool notBelowRight = (i + 1 == n || !std::isfinite(data[i + 1]) || val >= data[i + 1]);
652:         if (!notBelowLeft || !notBelowRight) {
653:             continue;
654:         }
655: 
656:         // 如果是平顶峰，仅保留平顶区间的首个点避免重复
657:         if (i > 0 && data[i - 1] == val) {
658:             continue;
659:         }
660: 
661:         // 2. 向左检测谷底落差：在遇到更高点之前，必须向下掉落至少 kExcursion
662:         float leftMin = val;
663:         bool leftValid = false;
664:         for (std::size_t l = i; l > 0; --l) {
665:             const float lv = data[l - 1];
666:             if (!std::isfinite(lv)) {
667:                 break;
668:             }
669:             if (lv > val) {
670:                 // 遇到更高点，说明当前点仅处于某个更高主峰的侧翼上，不是独立山头
671:                 break;
672:             }
673:             if (lv < leftMin) {
